export function salaryOwnerQaAuthority(){return{version:'municipal-owner-salary-authority.v1',scope:{tenantId:salaryOwnerQaId(1),membershipId:salaryOwnerQaId(2),bindingId:salaryOwnerQaId(3),companyId:101},authority:{version:'municipal-adoption-owner-authority.v1',policyVersion:'tenant-owner-adoption-policy.v1',policySha256:'3cd05ec553d4e19e511b4d755224efe36a470a02502704a621dec608ad312305',actor:{personId:salaryOwnerQaId(4),email:'owner-salary@example.invalid',identityVersion:2,sessionId:salaryOwnerQaId(5),sessionVersion:3,releaseSha:'a'.repeat(40)}},policy:{version:OWNER_SALARY_POLICY.version,sha256:OWNER_SALARY_POLICY_SHA256},scopeVersion:'b'.repeat(64)};}
export async function salaryOwnerQaPreview(){const items=salaryOwnerQaItems(),value={version:'municipal-owner-salary-preview.v1',decisionMode:'owner',independence:false,context:salaryOwnerQaAuthority(),proposal:{id:salaryOwnerQaId(6),requestSha256:'c'.repeat(64),baseVersion:'d'.repeat(64),classificationVersion:'f'.repeat(64),baseItems:items,items:items.map(r=>({...r,label:r.label+' revisada'})),reason:'Preparación sintética completa',authorLabel:'Responsable sintético',createdAt:'2026-10-15T12:00:00+00:00'},itemsSha256:null,current:true};value.itemsSha256=await adoptionReviewHash(value.proposal.items);return{...value,previewSha256:await adoptionReviewHash(value)};}
